import os
import numpy as np
import pandas as pd
import gurobipy as gp
from gurobipy import GRB


def transportation_lp_gurobi(df_demand, df_capacity, df_cost, model_name):
demand_list = df_demand['demand'].tolist()
capacity_list = df_capacity['supply_capacity'].tolist()

supply_num = len(capacity_list)
product_num = len(demand_list)

model = gp.Model(model_name)

vars_x = {}
for i in range(supply_num):
for j in range(product_num):
vars_x[i, j] = model.addVar(
vtype=GRB.CONTINUOUS,
lb=0.0,
name=f"x_{i}_{j}"
)

obj = gp.quicksum(
df_cost.iloc[i, j + 1] * vars_x[i, j]
for i in range(supply_num)
for j in range(product_num)
)
model.setObjective(obj, GRB.MINIMIZE)

for j in range(product_num):
model.addConstr(
gp.quicksum(vars_x[i, j] for i in range(supply_num)) >= demand_list[j],
name=f"demand_constraint_{j}"
)

for i in range(supply_num):
model.addConstr(
gp.quicksum(vars_x[i, j] for j in range(product_num)) <= capacity_list[i],
name=f"capacity_constraint_{i}"
)

model.setParam("TimeLimit", 300)

model.optimize()

if model.status == GRB.OPTIMAL:
print(f"Objective value: {model.ObjVal}")
lp_path = f"{model_name}.lp"
model.write(lp_path)
print(f"Model written to {lp_path}")

print("\nVariable values:")
for i in range(supply_num):
for j in range(product_num):
if vars_x[i, j].X > 1e-6: # Print only variables with significant values
print(f"x_{i}_{j} = {vars_x[i, j].X}")

elif model.status == GRB.TIME_LIMIT:
print("Time limit reached.")
if model.SolCount > 0:
print(f"Best objective found: {model.ObjVal}")
print("\nVariable values of incumbent solution:")
for i in range(supply_num):
for j in range(product_num):
if vars_x[i, j].X > 1e-6: # Print only variables with significant values
print(f"x_{i}_{j} = {vars_x[i, j].X}")
else:
print("No feasible solution found within time limit.")
else:
print(f"Optimization ended with status {model.status}")


if __name__ == "__main__":
model_name = "TP4"

df_demand = pd.read_csv(
"Data/TP4/customer_demand.csv"
)
df_capacity = pd.read_csv(
"Data/TP4/supply_capacity.csv"
)
df_cost = pd.read_csv(
"Data/TP4/transportation_costs.csv"
)

transportation_lp_gurobi(df_demand, df_capacity, df_cost, model_name)
print(f"Successfully loaded and written {model_name}.lp")

import csv
from pathlib import Path

import gurobipy as gp
from gurobipy import GRB


def read_csv_rows(path: Path) -> list[list[str]]:
with path.open("r", encoding="utf-8-sig", newline="") as handle:
return list(csv.reader(handle))


def solve_mixture3():
mixture_root = Path("Test_Dataset") / "Large-scale-or" / "Mixture_testing"
rows = read_csv_rows(mixture_root / "Mixture3" / "43.csv")

equipment = {row[0]: row for row in rows[1:8]}
raw_cost = {
"I": float(rows[8][1]),
"II": float(rows[8][2]),
"III": float(rows[8][3]),
}
price = {
"I": float(rows[9][1]),
"II": float(rows[9][2]),
"III": float(rows[9][3]),
}

used = {
("A1", "I"): 5.0,
("A1", "II"): 10.0,
("A2", "I"): 7.0,
("A2", "II"): 9.0,
("A2", "III"): 12.0,
("B1", "I"): 6.0,
("B1", "II"): 8.0,
("B2", "I"): 4.0,
("B2", "III"): 11.0,
("B3", "I"): 7.0,
}

cap = {k: float(v[4]) for k, v in equipment.items()}
cost_rate = {k: float(v[5]) / float(v[4]) for k, v in equipment.items()}

model = gp.Model("Mixture3")

x = {key: model.addVar(lb=0.0, name=f"x_{key[0]}_{key[1]}") for key in used}

total_A = {
"I": x["A1", "I"] + x["A2", "I"],
"II": x["A1", "II"] + x["A2", "II"],
"III": x["A2", "III"],
}
total_B = {
"I": x["B1", "I"] + x["B2", "I"] + x["B3", "I"],
"II": x["B1", "II"],
"III": x["B2", "III"],
}

revenue_minus_raw = gp.quicksum(
(price[p] - raw_cost[p]) * total_A[p] for p in ("I", "II", "III")
)
machine_cost = gp.quicksum(
cost_rate[e] * used[e, p] * x[e, p] for (e, p) in used
)

model.setObjective(revenue_minus_raw - machine_cost, GRB.MAXIMIZE)

model.addConstr(
used["A1", "I"] * x["A1", "I"] + used["A1", "II"] * x["A1", "II"] <= cap["A1"],
name="cap_A1",
)
model.addConstr(
used["A2", "I"] * x["A2", "I"]
+ used["A2", "II"] * x["A2", "II"]
+ used["A2", "III"] * x["A2", "III"] <= cap["A2"],
name="cap_A2",
)
model.addConstr(
used["B1", "I"] * x["B1", "I"] + used["B1", "II"] * x["B1", "II"] <= cap["B1"],
name="cap_B1",
)
model.addConstr(
used["B2", "I"] * x["B2", "I"] + used["B2", "III"] * x["B2", "III"] <= cap["B2"],
name="cap_B2",
)
model.addConstr(
used["B3", "I"] * x["B3", "I"] <= cap["B3"],
name="cap_B3",
)

for p in ("I", "II", "III"):
model.addConstr(total_A[p] == total_B[p], name=f"balance_{p}")

model.Params.OutputFlag = 0
model.optimize()

if model.Status == GRB.OPTIMAL:
print(f"Objective value: {model.ObjVal}")
for v in model.getVars():
if abs(v.X) > 1e-9:
print(f"{v.VarName} = {v.X}")
model.write("Mixture3.lp")
print("Model written to Mixture3.lp")
else:
print(f"Optimization ended with status {model.Status}")


if __name__ == "__main__":
solve_mixture3()

import csv
from pathlib import Path

import gurobipy as gp
from gurobipy import GRB


def read_csv_rows(path: Path) -> list[list[str]]:
with path.open("r", encoding="utf-8-sig", newline="") as handle:
return list(csv.reader(handle))


def solve_mixture18():
mixture_root = Path("Test_Dataset") / "Large-scale-or" / "Mixture_testing"

time_rows = read_csv_rows(mixture_root / "Mixture18" / "device_time.csv")
cap_rows = read_csv_rows(mixture_root / "Mixture18" / "monthly_device_capacity.csv")
profit_rows = read_csv_rows(mixture_root / "Mixture18" / "unit_product_profits.csv")

devices = [row[0] for row in time_rows[1:]]
products = time_rows[0][1:]

times = {row[0]: [float(v) for v in row[1:]] for row in time_rows[1:]}
caps = {row[0]: float(row[1]) for row in cap_rows[1:]}
profits = {row[0]: float(row[1]) for row in profit_rows[1:]}

model = gp.Model("Mixture18")

x = model.addVars(products, lb=0.0, name="x")

model.setObjective(
gp.quicksum(profits[p] * x[p] for p in products),
GRB.MAXIMIZE,
)

for d in devices:
model.addConstr(
gp.quicksum(times[d][j] * x[products[j]] for j in range(len(products))) <= caps[d],
name=f"capacity_{d}",
)

model.Params.OutputFlag = 0
model.optimize()

if model.Status == GRB.OPTIMAL:
print(f"Objective value: {model.ObjVal}")
for v in model.getVars():
if abs(v.X) > 1e-9:
print(f"{v.VarName} = {v.X}")
model.write("Mixture18.lp")
print("Model written to Mixture18.lp")
else:
print(f"Optimization ended with status {model.Status}")


if __name__ == "__main__":
solve_mixture18()

