\documentclass{article}
\usepackage{amsmath, amssymb}

\begin{document}

\textbf{Parameters:}
\begin{itemize}
\item Goal weights:
\[
P_1 = 20000,\qquad P_2 = 3000,\qquad P_3 = 1.
\]
\end{itemize}
\textbf{Decision Variables:}
\begin{itemize}
\item $x_1$: Weekly production quantity of Type A.
\item $x_2$: Weekly production quantity of Type B.
\item $d_1^-, d_1^+$: Negative and positive deviations from the profit goal.
\item $d_2^-, d_2^+$: Negative and positive deviations from the Type A production goal.
\item $u_1,u_2,u_3$: Idle hours in manufacturing, assembly, and inspection.
\end{itemize}

\textbf{Net profit per unit:}
\[
\pi_1 = 650 - 20(12) - 5(8) - 3(10) = 340,
\]
\[
\pi_2 = 725 - 7(8) - 6(10) = 609.
\]

\textbf{Goal Programming Formulation:}
\begin{align*}
\min \quad & P_1 d_1^- + P_2 d_2^- + P_3(12u_1 + 8u_2 + 10u_3) \\[4pt]
\text{s.t.} \quad
& 340x_1 + 609x_2 + d_1^- - d_1^+ = 3000
&& (\text{Profit goal } p_1) \\[4pt]
& x_1 + d_2^- - d_2^+ = 5
&& (\text{Minimum Type A goal } p_2) \\[4pt]
& 20x_1 + u_1 = 120
&& (\text{Manufacturing capacity}) \\[4pt]
& 5x_1 + 7x_2 + u_2 = 80
&& (\text{Assembly capacity}) \\[4pt]
& 3x_1 + 6x_2 + u_3 = 40
&& (\text{Inspection capacity}) \\[4pt]
& x_1,x_2 \in \mathbb{Z}_+
&& (\text{Integer and nonnegative}) \\[4pt]
& d_1^-,d_1^+,d_2^-,d_2^+,u_1,u_2,u_3 \ge 0
\end{align*}
\end{align*}

\end{document}

\documentclass{article}
\usepackage{amsmath, amssymb}

\begin{document}
\textbf{Sets and Parameters:}
\begin{itemize}
\item $T=\{1,2,\dots,10\}$: Set of planning stages.
\item $r_j$: Tool requirement in stage $j \in T$, where $(r_1,\dots,r_{10})=(3,5,2,4,6,5,4,3,2,1)$.
\end{itemize}

\textbf{Decision Variables:}
\begin{itemize}
\item $x_j$: Number of new tools purchased at the beginning of stage $j$, $j \in T$.
\item $y_j$: Number of tools used in stage $j$ that are sent to slow repair, $j \in T$.
\item $z_j$: Number of tools used in stage $j$ that are sent to fast repair, $j \in T$.
\item $I_j$: Number of usable tools available at the beginning of stage $j$, $j \in T$.
\end{itemize}

\textbf{Mathematical Formulation:}
\begin{align*}
\min \quad 
& \sum_{j \in T} \left( 10 x_j + y_j + 3 z_j \right) \\[4pt]
\text{s.t.} \quad
& I_1 = 0
&& (\text{No initial usable tools}) \\[4pt]
& I_j + x_j \ge r_j, \quad \forall j \in T
&& (\text{Demand satisfaction}) \\[4pt]
& y_j + z_j \le r_j, \quad \forall j \in T
&& (\text{Only used tools can be repaired}) \\[4pt]
& I_{j+1} = I_j + x_j - r_j + y_{j-3} + z_{j-1}, \quad \forall j=1,\dots,9
&& (\text{Inventory balance}) \\[4pt]
& y_t = 0,\quad z_t = 0, \quad \forall t \le 0
&& (\text{Repair returns before stage 1 are zero}) \\[4pt]
& x_j,y_j,z_j,I_j \in \mathbb{Z}_+, \quad \forall j \in T
&& (\text{Integer and nonnegative})
\end{align*}


\end{document}

\documentclass{article}
\usepackage{amsmath, amssymb}

\textbf{Sets and Parameters:}
\begin{itemize}
\item $W=\{A,B,C,D\}$: Set of workshops.
\item $C=\{1,2,3\}$: Set of components.
\item $H_w$: Available production hours of workshop $w\in W$, where
\[
H_A=100,\quad H_B=150,\quad H_C=80,\quad H_D=200.
\]
\item $r_{wc}$: Production rate (units/hour) of component $c\in C$ in workshop $w\in W$, where
\[
\begin{array}{c|ccc}
& 1 & 2 & 3 \\
\hline
A & 10 & 15 & 5 \\
B & 15 & 10 & 5 \\
C & 20 & 5 & 10 \\
D & 10 & 15 & 20
\end{array}
\]
\end{itemize}

\textbf{Decision Variables:}
\begin{itemize}
\item $x_{wc}$: Number of hours workshop $w\in W$ allocates to producing component $c\in C$.
\item $q$: Number of completed products.
\end{itemize}

\textbf{Mathematical Formulation:}
\begin{align*}
\max \quad
& q \\[4pt]
\text{s.t.} \quad
& \sum_{c\in C} x_{wc} \le H_w, \quad \forall w\in W
&& (\text{Workshop-hour constraints}) \\[4pt]
& \sum_{w\in W} r_{w1}x_{w1} \ge q
&& (\text{Component 1 requirement}) \\[4pt]
& \sum_{w\in W} r_{w2}x_{w2} \ge q
&& (\text{Component 2 requirement}) \\[4pt]
& \sum_{w\in W} r_{w3}x_{w3} \ge q
&& (\text{Component 3 requirement}) \\[4pt]
& x_{wc} \ge 0,\quad \forall w\in W,\; c\in C
&& (\text{Nonnegativity constraints}) \\[4pt]
& q \in \mathbb{Z}_+
&& (\text{Integer number of completed products})
\end{align*}

\end{document}

