\item $y_{C1},y_{C2}$: Binary variables indicating the selected segment for product C.
\end{itemize}

\textbf{Mathematical Formulation:}
\begin{align*}
\max \quad
& 10x_{A1}+9x_{A2}+8x_{A3}+7x_{A4}
+6x_{B1}+4x_{B2}+3x_{B3}
+5x_{C1}+4x_{C2} \\[4pt]
