&& (\text{choose one segment for A}) \\[4pt]
& y_{B1}+y_{B2}+y_{B3}=1
&& (\text{choose one segment for B}) \\[4pt]
& y_{C1}+y_{C2}=1
&& (\text{choose one segment for C}) \\[4pt]
& 0 \le x_{A1} \le 40y_{A1}
&& (\text{A, segment 1}) \\[4pt]
& 40y_{A2} \le x_{A2} \le 100y_{A2}
&& (\text{A, segment 2}) \\[4pt]
& 100y_{A3} \le x_{A3} \le 150y_{A3}
&& (\text{A, segment 3}) \\[4pt]
& 150y_{A4} \le x_{A4}
&& (\text{A, segment 4}) \\[4pt]
& 0 \le x_{B1} \le 50y_{B1}
&& (\text{B, segment 1}) \\[4pt]
& 50y_{B2} \le x_{B2} \le 100y_{B2}
&& (\text{B, segment 2}) \\[4pt]
& 100y_{B3} \le x_{B3}
&& (\text{B, segment 3}) \\[4pt]
& 0 \le x_{C1} \le 100y_{C1}
&& (\text{C, segment 1}) \\[4pt]
& 100y_{C2} \le x_{C2}
&& (\text{C, segment 2}) \\[4pt]
& x_{A1},x_{A2},x_{A3},x_{A4},
x_{B1},x_{B2},x_{B3},
x_{C1},x_{C2}\in\mathbb{Z}_+
&& (\text{integer and nonnegative}) \\[4pt]
& y_{A1},y_{A2},y_{A3},y_{A4},
y_{B1},y_{B2},y_{B3},
y_{C1},y_{C2}\in\{0,1\}
&& (\text{binary segment variables})
\end{align*}

\end{document}

\documentclass{article}
\usepackage{amsmath, amssymb}

\textbf{Sets and Parameters:}
\begin{itemize}
\item $N=\{1,2,3,4,5,6,7\}$: Set of locations.
\item $c_{ij}$: Distance from location $i$ to location $j$, where the distance matrix is symmetric and given by
\[
\begin{array}{c|ccccccc}
& 1 & 2 & 3 & 4 & 5 & 6 & 7 \\
\hline
1 & - & 86 & 49 & 57 & 31 & 69 & 50 \\
2 & 86 & - & 68 & 79 & 93 & 24 & 5 \\
3 & 49 & 68 & - & 16 & 7 & 72 & 67 \\
4 & 57 & 79 & 16 & - & 90 & 69 & 1 \\
5 & 31 & 93 & 7 & 90 & - & 86 & 59 \\
6 & 69 & 24 & 72 & 69 & 86 & - & 81 \\
7 & 50 & 5 & 67 & 1 & 59 & 81 & -
\end{array}
\]
\end{itemize}

\textbf{Decision Variables:}
\begin{itemize}
\item $x_{ij}$: Binary variable equal to 1 if the salesman travels directly from location $i$ to location $j$, 0 otherwise, for all $i,j\in N$, $i\ne j$.
\item $u_i$: Ordering variable for location $i$, for all $i\in N$.
\end{itemize}

\textbf{Mathematical Formulation:}
\begin{align*}
\min \quad
& \sum_{i\in N}\sum_{\substack{j\in N\\ j\ne i}} c_{ij}x_{ij} \\[4pt]
\text{s.t.} \quad
& \sum_{\substack{j\in N\\ j\ne i}} x_{ij}=1, \quad \forall i\in N
&& (\text{Leave each location exactly once}) \\[4pt]
& \sum_{\substack{i\in N\\ i\ne j}} x_{ij}=1, \quad \forall j\in N
&& (\text{Enter each location exactly once}) \\[4pt]
& u_i-u_j+7x_{ij}\le 6, \quad \forall i,j\in N\setminus\{1\},\ i\ne j
&& (\text{Subtour elimination}) \\[4pt]
& u_1=1
&& (\text{Start at location 1}) \\[4pt]
& 2\le u_i\le 7,\quad \forall i\in N\setminus\{1\}
&& (\text{Ordering bounds}) \\[4pt]
& x_{ij}\in\{0,1\}, \quad \forall i,j\in N,\ i\ne j
&& (\text{Binary routing variables})
\end{align*}

\end{document}

\documentclass{article}
\usepackage{amsmath, amssymb}

\textbf{Sets and Parameters:}
\begin{itemize}
\item $F=\{1,2\}$: Set of factories.
\item $L=\{1,2\}$: Set of locations.
\item $v_{ip}$: Transportation volume associated with assigning factory $i\in F$ to location $p\in L$, where
\[
(v_{ip})=
\begin{pmatrix}
10 & 20\\
30 & 40
\end{pmatrix}.
\]
\item $c_{ip}$: Unit transportation cost associated with assigning factory $i\in F$ to location $p\in L$, where
\[
(c_{ip})=
\begin{pmatrix}
5 & 8\\
6 & 7
\end{pmatrix}.
\]
\end{itemize}

\textbf{Decision Variables:}
\begin{itemize}
\item $x_{ip}$: Binary variable equal to 1 if factory $i\in F$ is assigned to location $p\in L$, and 0 otherwise.
\end{itemize}

\textbf{Mathematical Formulation:}
\begin{align*}
\min \quad
& \sum_{i\in F}\sum_{p\in L} v_{ip}c_{ip}x_{ip} \\[4pt]
\text{s.t.} \quad
& \sum_{p\in L} x_{ip}=1, \quad \forall i\in F
&& (\text{Each factory is assigned to exactly one location}) \\[4pt]
& \sum_{i\in F} x_{ip}=1, \quad \forall p\in L
&& (\text{Each location receives exactly one factory}) \\[4pt]
& x_{ip}\in\{0,1\}, \quad \forall i\in F,\; p\in L
&& (\text{Binary assignment variables})
\end{align*}

\end{document}

Solver Code Grubi Python:
import gurobipy as gp
from gurobipy import GRB

# Set of quarters
Q = [1, 2, 3, 4] # 1=Winter, 2=Spring, 3=Summer, 4=Autumn

# Parameters
p = {
1: 410,
2: 430,
3: 460,
4: 450
}

s = {
1: 425,
2: 440,
3: 465,
4: 455
}

D = {
1: 100,
2: 140,
3: 200,
4: 160
}

# Storage cost h_ij
h = {}
for i in Q:
for j in Q:
if j >= i:
if j == i:
h[i, j] = 0
else:
h[i, j] = 70 + 100 * (j - i)

# Feasible (i,j) pairs: buy in quarter i, sell in quarter j >= i
pairs = [(i, j) for i in Q for j in Q if j >= i]

# Create model
m = gp.Model("Timber_Inventory_Planning")

# Decision variables
x = m.addVars(pairs, vtype=GRB.CONTINUOUS, lb=0, name="x")
I = m.addVars([1, 2, 3, 4], vtype=GRB.CONTINUOUS, lb=0, name="I")

# Objective function
m.setObjective(
gp.quicksum((s[j] - p[i] - h[i, j]) * x[i, j] for (i, j) in pairs),
GRB.MAXIMIZE
)

# Sales limits
for j in Q:
m.addConstr(
gp.quicksum(x[i, j] for i in Q if i <= j) <= D[j],
name=f"sales_limit_{j}"
)

# Ending inventory definition
for t in [1, 2, 3, 4]:
m.addConstr(
I[t] == gp.quicksum(
x[i, j] for i in Q if i <= t for j in Q if j > t and j >= i
),
name=f"inventory_def_{t}"
)

# Warehouse capacity
for t in [1, 2, 3]:
m.addConstr(
I[t] <= 20,
name=f"warehouse_capacity_{t}"
)

# All inventory must be sold by the end of autumn
m.addConstr(I[4] == 0, name="final_inventory_zero")

# Solve the model
m.optimize()

# Print solution
if m.status == GRB.OPTIMAL:
print(f"Optimal annual profit: {m.objVal:.2f} (in 10,000 yuan)\n")

print("Optimal purchase-sale plan (nonzero only):")
for (i, j) in pairs:
if x[i, j].X > 1e-6:
print(f" Buy in quarter {i}, sell in quarter {j}: {x[i, j].X:.2f} m^3")

else:
print("No optimal solution found.")

Math Formulation in Latex:
\documentclass{article}
\usepackage{amsmath, amssymb}

\textbf{Decision Variables:}
\begin{itemize}
\item $x_1$: Weekly production quantity of product X.
\item $x_2$: Weekly production quantity of product Y.
\end{itemize}

\textbf{Mathematical Formulation:}
\begin{align*}
\max \quad
& 20x_1 + 30x_2
- \frac{10}{60}(13x_1+19x_2)
- \frac{2}{60}(20x_1+29x_2) \\[4pt]
\text{s.t.} \quad
& 13x_1 + 19x_2 \le 2400
&& (\text{Machine time constraint}) \\[4pt]
& 20x_1 + 29x_2 \le 2100
&& (\text{Craftsman time constraint}) \\[4pt]
& x_1 \ge 10
&& (\text{Minimum production of X}) \\[4pt]
& x_1,x_2 \in \mathbb{Z}_+
&& (\text{Integer and nonnegative production}) \\[4pt]
& x_1, x_2 \ge 0
